Explain policy-based design using this <code>Pricer&lt;Model, Payoff&gt;</code>. What does the program print, and how does it compare with a Python strategy object?<br><pre><code>#include &lt;algorithm&gt;
#include &lt;cmath&gt;
#include &lt;iostream&gt;

struct BlackScholesTerminal {
    double S0 = 100.0, r = 0.05, sigma = 0.2, T = 1.0;
    double terminal(double z) const {
        return S0 * std::exp((r - 0.5 * sigma * sigma) * T + sigma * std::sqrt(T) * z);
    }
    double discount() const { return std::exp(-r * T); }
};

struct CallPayoff {
    double K = 100.0;
    double operator()(double S) const { return std::max(S - K, 0.0); }
};

template &lt;typename Model, typename Payoff&gt;
class Pricer {
public:
    Pricer(Model m, Payoff p) : model_(m), payoff_(p) {}
    double price_on_scenario(double z) const {
        return model_.discount() * payoff_(model_.terminal(z));
    }
private:
    Model model_;
    Payoff payoff_;
};

int main() {
    Pricer&lt;BlackScholesTerminal, CallPayoff&gt; p{BlackScholesTerminal{}, CallPayoff{}};
    std::cout &lt;&lt; p.price_on_scenario(0.0) &lt;&lt; '\n';
    std::cout &lt;&lt; p.price_on_scenario(1.0) &lt;&lt; '\n';
}</code></pre>

